CREATE TABLE order_cart_item(id BIGINT NOT NULL,user_id BIGINT NOT NULL,sku_id BIGINT NOT NULL,quantity BIGINT UNSIGNED NOT NULL,selected BOOLEAN NOT NULL DEFAULT TRUE,version BIGINT UNSIGNED NOT NULL DEFAULT 0,created_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),updated_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) ON UPDATE CURRENT_TIMESTAMP(6),PRIMARY KEY(id),UNIQUE KEY uk_order_cart_user_sku(user_id,sku_id),INDEX idx_order_cart_user_selected(user_id,selected),CONSTRAINT chk_order_cart_quantity CHECK(quantity>0));
CREATE TABLE order_main(id BIGINT NOT NULL,order_no VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,request_id VARCHAR(128) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,user_id BIGINT NOT NULL,status VARCHAR(24) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,total_amount DECIMAL(18,2) NOT NULL,currency CHAR(3) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,remark VARCHAR(500) NULL,version BIGINT UNSIGNED NOT NULL DEFAULT 0,expires_at DATETIME(6) NULL,paid_at DATETIME(6) NULL,cancelled_at DATETIME(6) NULL,created_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),updated_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) ON UPDATE CURRENT_TIMESTAMP(6),PRIMARY KEY(id),UNIQUE KEY uk_order_no(order_no),UNIQUE KEY uk_order_user_request(user_id,request_id),INDEX idx_order_user_created(user_id,created_at),INDEX idx_order_status_expiry(status,expires_at),CONSTRAINT chk_order_total CHECK(total_amount>=0));
CREATE TABLE order_item(id BIGINT NOT NULL,order_id BIGINT NOT NULL,sku_id BIGINT NOT NULL,sku_code VARCHAR(64) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,product_name VARCHAR(200) NOT NULL,unit_price DECIMAL(18,2) NOT NULL,quantity BIGINT UNSIGNED NOT NULL,subtotal DECIMAL(18,2) NOT NULL,product_snapshot JSON NOT NULL,PRIMARY KEY(id),INDEX idx_order_item_order(order_id),CONSTRAINT fk_order_item_order FOREIGN KEY(order_id) REFERENCES order_main(id) ON DELETE RESTRICT,CONSTRAINT chk_order_item_amount CHECK(unit_price>=0 AND quantity>0 AND subtotal>=0));
CREATE TABLE order_address_snapshot(order_id BIGINT NOT NULL,recipient_name VARCHAR(80) NOT NULL,recipient_phone VARCHAR(32) NOT NULL,country_code CHAR(2) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,province_code VARCHAR(16) NULL,province_name VARCHAR(64) NOT NULL,city_name VARCHAR(64) NOT NULL,district_name VARCHAR(64) NOT NULL,address_detail VARCHAR(500) NOT NULL,postal_code VARCHAR(16) NULL,PRIMARY KEY(order_id),CONSTRAINT fk_order_address_order FOREIGN KEY(order_id) REFERENCES order_main(id) ON DELETE RESTRICT);
CREATE TABLE order_state_history(id BIGINT NOT NULL,order_id BIGINT NOT NULL,from_status VARCHAR(24) NULL,to_status VARCHAR(24) NOT NULL,event_id VARCHAR(64) CHARACTER SET ascii COLLATE ascii_bin NULL,reason VARCHAR(500) NULL,occurred_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),PRIMARY KEY(id),UNIQUE KEY uk_order_history_event(event_id),INDEX idx_order_history_order_time(order_id,occurred_at));
CREATE TABLE order_outbox(id VARCHAR(64) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,aggregate_id VARCHAR(64) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,event_type VARCHAR(128) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,payload_json JSON NOT NULL,status VARCHAR(16) CHARACTER SET ascii COLLATE ascii_bin NOT NULL DEFAULT 'PENDING',retry_count INT UNSIGNED NOT NULL DEFAULT 0,next_retry_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),created_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),published_at DATETIME(6) NULL,PRIMARY KEY(id),INDEX idx_order_outbox_dispatch(status,next_retry_at));
CREATE TABLE order_inbox(event_id VARCHAR(64) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,event_type VARCHAR(128) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,processed_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),PRIMARY KEY(event_id));
